sys_script_include.script:
var TrainingSystemUtils = Class.create();
TrainingSystemUtils.prototype = {
    initialize: function() {},

    refQualAgendas: function() {
        var agendasNotToBeShown = [];
        var trainingCount = {};

        var grEnrollment = new GlideRecord("x_1593177_training_enrollment");
        grEnrollment.addEncodedQuery("agenda.instructorDYNAMIC90d1921e5f510100a9ad2572f2b477fe^ORenrolled_userDYNAMIC90d1921e5f510100a9ad2572f2b477fe");
        grEnrollment.query();

        while (grEnrollment.next()) {
            var agendaId = grEnrollment.agenda.sys_id.toString();
            agendasNotToBeShown.push(agendaId);

            var trainingId = grEnrollment.agenda.training.toString();
            if (trainingId) {
                if (!trainingCount[trainingId]) {
                    trainingCount[trainingId] = 0;
                }
                trainingCount[trainingId]++;
            }
        }

        var agendasToBeShown = [];
        var grAgendas = new GlideRecord("x_1593177_training_agenda");
        grAgendas.addEncodedQuery("date>javascript:gs.endOfToday()^remaining_vacancies>0^ORDERBYASCdate");
        grAgendas.query();

        while (grAgendas.next()) {
            var trainId = grAgendas.training.toString();

            if (trainingCount[trainId] && trainingCount[trainId] >= 3) {
                continue;
            }

            if (agendasNotToBeShown.indexOf(grAgendas.getUniqueValue()) == -1) {
                agendasToBeShown.push(grAgendas.getUniqueValue());
            }
        }

        return "sys_idIN" + agendasToBeShown.join(",");
    },

    type: 'TrainingSystemUtils'
};
